export function App() {
  const [selectedTheme, setSelectedTheme] = useState<'light' | 'dark'>('light');
  const lineData = [
    { label: 'Пн', value: 18 },
    { label: 'Вт', value: 32 },
    { label: 'Ср', value: 24 },
    { label: 'Чт', value: 41 },
    { label: 'Пт', value: 36 },
    { label: 'Сб', value: 53 },
    { label: 'Вс', value: 47 },
  ];

  return (
    <ThemeProvider theme={selectedTheme} scoped>
      <main className="app-screen">
        <div className="app-card">
          <header className="app-header">
            <div>
              <p className="app-overline">Аналитика</p>
              <h1 className="app-title">Активность за неделю</h1>
            </div>
            <SegmentedRadioGroup name="theme" size="s" value={selectedTheme} onUpdate={setSelectedTheme}>
              <SegmentedRadioGroupOption value="light">Светлая</SegmentedRadioGroupOption>
              <SegmentedRadioGroupOption value="dark">Тёмная</SegmentedRadioGroupOption>
            </SegmentedRadioGroup>
          </header>
          <p className="app-description">График адаптируется к текущей цветовой теме интерфейса.</p>
          <LineChart data={lineData} />
        </div>
      </main>
    </ThemeProvider>
  );
}

